$prog = "const { S3Client,PutObjectCommand,ListObjectsV2Command }=require('@aws-sdk/client-s3');(async()=>{ const cli=new S3Client({region:process.env.S3_REGION||'auto',endpoint:process.env.S3_ENDPOINT,forcePathStyle:true}); const M=process.env.S3_BUCKET; console.log('REGION_APP=',process.env.S3_REGION); console.log('ENDPOINT_APP_OK=', (process.env.S3_ENDPOINT||'').includes('be8db66e')?'SI':'NO'); console.log('BUCKET_APP=',M); console.log('AK_APP=',process.env.AWS_ACCESS_KEY_ID?'SET':'FALTA'); console.log('SK_APP=',process.env.AWS_SECRET_ACCESS_KEY?'SET':'FALTA'); try{ await cli.send(new PutObjectCommand({Bucket:M,Key:'prod-' + Date.now()+'.txt',Body:'x\n'})); console.log('PUT_PROD=OK'); }catch(e){ console.log('PUT_PROD=FALLO', e.name, String(e.message||'').slice(0,120)); } })();"
$esc = $prog.Replace('"','\"')
fly ssh console -C "node -e \"$esc\"" 2>&1
